// Generated illustration system. One consistent style per category, one motif per product noun,
// deterministic from the product seed. All art is inline SVG, viewBox 0 0 200 200.
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);
function mulberry(a) {
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const hex = (h) => (h.length === 4 ? '#' + [...h.slice(1)].map((c) => c + c).join('') : h), hx = (h) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16));
const mix = (a, b, t) => '#' + hx(hex(a)).map((v, i) => Math.round(v + (hx(hex(b))[i] - v) * t).toString(16).padStart(2, '0')).join('');

// ---- tiny shape helpers ----
const R = (x, y, w, h, rx, f, e = '') => `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${rx}" fill="${f}" ${e}/>`;
const C = (x, y, r, f, e = '') => `<circle cx="${x}" cy="${y}" r="${r}" fill="${f}" ${e}/>`;
const E = (x, y, rx, ry, f, e = '') => `<ellipse cx="${x}" cy="${y}" rx="${rx}" ry="${ry}" fill="${f}" ${e}/>`;
const P = (d, f, e = '') => `<path d="${d}" fill="${f}" ${e}/>`;
const S = (d, s, w, e = '') => `<path d="${d}" fill="none" stroke="${s}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round" ${e}/>`;
const gl = (x, y, w, h, rx) => R(x, y, w, h, rx, '#fff', 'opacity=".24"');
const sd = (x, y, w, h, rx) => R(x, y, w, h, rx, '#000', 'opacity=".12"');
const bars = (x, y, w, n, f, gap = 9, h = 5) => Array.from({ length: n }, (_, i) => R(x, y + i * gap, i % 2 ? w * 0.7 : w, h, 2.5, f)).join('');

