function bgLayer(cat, id, v) {
  const c = CAT[cat];
  const [t, b] = v === 4 ? [c.bg[1], mix(c.bg[1], '#ffffff', 0.35)] : c.bg;
  const defs = `<linearGradient id="${id}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${t}"/><stop offset="1" stop-color="${b}"/></linearGradient>`;
  let deco = '';
  switch (cat) {
    case 'electronics': deco = Array.from({ length: 6 }, (_, i) => Array.from({ length: 6 }, (_, j) => C(20 + i * 32, 20 + j * 32, 1.4, '#1f3a4d', 'opacity=".12"')).join('')).join('') + C(100, 96, 70, '#fff', 'opacity=".5"'); break;
    case 'kitchen': deco = S('M0 40h200M0 80h200M0 120h200M40 0v150M100 0v150M160 0v150', '#b8683a', 1, 'opacity=".1"') + R(0, 152, 200, 48, 0, '#c99d68', 'opacity=".35"') + R(0, 152, 200, 4, 0, '#fff', 'opacity=".4"'); break;
    case 'books': deco = R(0, 160, 200, 40, 0, '#8a6a4a', 'opacity=".5"') + R(0, 160, 200, 4, 0, '#fff', 'opacity=".3"') + C(30, 36, 20, '#fff', 'opacity=".35"') + C(176, 70, 12, '#fff', 'opacity=".3"'); break;
    case 'fashion': deco = S('M-10 60L60 -10M-10 120L120 -10M-10 180L180 -10M40 210L210 40M100 210L210 100', '#fff', 10, 'opacity=".22"') + C(100, 100, 66, '#fff', 'opacity=".28"'); break;
    case 'home': deco = R(0, 158, 200, 42, 0, '#c9b793', 'opacity=".6"') + R(0, 156, 200, 3, 0, '#fff', 'opacity=".5"') + R(138, 22, 44, 62, 3, '#fff', 'opacity=".4"') + S('M160 22v62M138 53h44', '#b9c4aa', 2); break;
    case 'toys': deco = [[30, 40, 8, '#e34b4b'], [170, 36, 6, '#2f7be0'], [24, 150, 7, '#2fae6b'], [176, 140, 9, '#8a4be0'], [152, 90, 4, '#f08a1c']].map(([x, y, r, f]) => C(x, y, r, f, 'opacity=".5"')).join('') + P('M44 20l8 14-16 0z', '#2f7be0', 'opacity=".4"') + R(160, 168, 14, 14, 3, '#e34b4b', 'opacity=".35" transform="rotate(20 167 175)"'); break;
    case 'grocery': deco = R(0, 156, 200, 44, 0, '#b88a4e', 'opacity=".45"') + S('M0 170h200M0 184h200', '#fff', 1.5, 'opacity=".3"') + P('M20 40q10-18 24 0q-10 14-24 0z', '#4c7a3a', 'opacity=".35"') + P('M164 60q10-18 24 0q-10 14-24 0z', '#4c7a3a', 'opacity=".3"'); break;
    default: deco = C(40, 44, 26, '#fff', 'opacity=".4"') + C(170, 60, 16, '#fff', 'opacity=".35"') + C(150, 150, 34, '#fff', 'opacity=".25"') + R(0, 160, 200, 40, 0, '#fff', 'opacity=".5"'); break;
  }
  return `<defs>${defs}</defs><rect width="200" height="200" fill="url(#${id})"/>${deco}`;
}

// ---- book covers: shared body + 19 emblems ----
function book(K, r, emblem) {
  const x = 52, y = 34, w = 96, h = 130;
  return sd(x + 5, y + 5, w, h, 5) + R(x, y, w, h, 5, K.m) + R(x, y, 10, h, 4, K.d) + R(x + 10, y, 2, h, 0, '#fff', 'opacity=".25"') + gl(x + 12, y, w - 14, 30, 0) +
    R(x + 22, y + 12, 58 - r() * 12, 6, 3, K.w) + R(x + 22, y + 24, 40 - r() * 10, 5, 2.5, K.w, 'opacity=".75"') +
    `<g transform="translate(100 98)">${emblem(K)}</g>` + R(x + 22, y + h - 22, 38, 4, 2, K.w, 'opacity=".7"') + R(x + 22, y + h - 14, 26, 4, 2, K.w, 'opacity=".5"');
}
