M['rubik cube'] = () => {
  const cs = ['#e34b4b', '#2f7be0', '#f2c14e', '#ffffff', '#2fae6b', '#f08a1c'];
  const face = (o, u, w, k, shade) => Array.from({ length: 9 }, (_, n) => {
    const i = n % 3, j = Math.floor(n / 3);
    const pt = (a, b) => `${o[0] + u[0] * a + w[0] * b} ${o[1] + u[1] * a + w[1] * b}`;
    return `<path d="M${pt(i, j)}L${pt(i + 1, j)}L${pt(i + 1, j + 1)}L${pt(i, j + 1)}z" fill="${mix(cs[(n * 5 + k) % 6], '#000000', shade)}" stroke="#15201e" stroke-width="2.4" stroke-linejoin="round"/>`;
  }).join('');
  return face([100, 36], [22, 12], [-22, 12], 0, 0) + face([34, 72], [22, 12], [0, 22], 2, 0.18) + face([166, 72], [-22, 12], [0, 22], 4, 0.32);
};
