export function art(p, v = 0) {
  const cat = CAT[p.category] ? p.category : 'electronics';
  const c = CAT[cat];
  const r = mulberry(p.seed);
  const m = c.mains[(Math.floor(r() * 997) + v) % c.mains.length];
  let a = c.acc[(Math.floor(r() * 997) + (v ? 1 : 0)) % c.acc.length];
  if (a === '#fff') a = mix(m, '#ffffff', 0.5);
  const K = { m, d: mix(m, '#000000', 0.28), l: mix(m, '#ffffff', 0.55), a, w: '#ffffff', bg: c.bg[0] };
  const noun = nounOf(p.title);
  let g;
  if (cat === 'books' && noun && EMB[noun]) g = book(K, r, EMB[noun]);
  else g = (M[noun] || DEFAULT)(K, r);
  const id = `ab${p.seed}_${v}`;
  const wall = WALL.has(noun);
  const shadow = wall ? '' : E(100, 168, 62, 6, '#000', 'opacity=".14"');
  const xf = v === 2 ? 'translate(-35 -30) scale(1.35)' : v === 3 ? 'rotate(-12 100 100) translate(0 4)' : v === 4 ? 'translate(18 10) scale(.82)' : '';
  return `<svg class="art" viewBox="0 0 200 200" role="img" aria-label="${esc(p.title)}" data-cat="${cat}">${bgLayer(cat, id, v)}<g${xf ? ` transform="${xf}"` : ''}>${shadow}${g}</g></svg>`;
}
export const motifCount = () => Object.keys(M).length + Object.keys(EMB).length;
